SELECT bucket, count(*) AS Aircraft FROM (
    SELECT CASE WHEN rate = 0 THEN '0' WHEN rate < 1 THEN '<1' WHEN rate < 2 THEN '1-2' WHEN rate < 3 THEN '2-3'
                WHEN rate < 5 THEN '3-5' WHEN rate < 10 THEN '5-10' ELSE '10+' END AS bucket
    FROM (
        SELECT tail, try_divide(1000 * sum(cxl_carrier), sum(flights)) AS rate
        FROM ${catalog}.faa.tail_day WHERE FlightDate BETWEEN CAST($__timeFrom AS DATE) AND CAST($__timeTo AS DATE) AND Reporting_Airline IN (${airline:singlequote}) AND tail != ''
        GROUP BY tail HAVING sum(completed) >= ${min_flights}
    )
)
GROUP BY bucket ORDER BY array_position(array('0', '<1', '1-2', '2-3', '3-5', '5-10', '10+'), bucket)
